        let pages = new PortalPages();
        if (oldEntity.pages) {
            pages = oldEntity.pages;
        }
        if (updatedFileds?.pages) {
            pages = PortalPages.handleUpdatePages(pages, updatedFileds);
            if (pages?.offering?.offerings?.length) {
