/**
 * Reads the EC2 instance inventory the collection microservices rely on.
 * <br><br>
 * This performs the same `ec2:DescribeInstances` read that the data gatherers perform, it is used to
 * prove that a set of credentials is actually able to collect usage data before the credentials are stored.
 *
 * @param creds The credentials (or credential provider) to read the inventory with
 * @param region The region to read the inventory in, defaults to `us-east-1`
 */
export const readInstanceInventory = async (creds, region = 'us-east-1'): Promise<void> => {
    const ec2Client = new EC2Client({ region, credentials: creds });
    await ec2Client.send(new DescribeInstancesCommand({}));
};
