import { CloudIAMConnection, CloudIAMLike } from '../entities/cloudIAMConnection.js';

/**
 * Validates the scraper role (`cloudIAM`) a customer wants to connect.
 * <br><br>
 * A blank `iamRoleArn` is a disconnect and is always valid, a block which names no role is invalid, and a
 * named role has to be assumable with the supplied external ID and able to read the instance inventory.
 */
@ValidatorConstraint({ name: 'ValidCloudIAMRule', async: true })
export class ValidCloudIAMRule implements ValidatorConstraintInterface {
    private message: string;

    async validate(cloudIAM: CloudIAMLike, args: ValidationArguments) {
        if (cloudIAM === undefined || cloudIAM === null) {
            // Nothing was sent, nothing to check, the currently saved value is kept
            return true;
        }
        if (!CloudIAMConnection.namesRole(cloudIAM)) {
            this.message = CloudIAMConnection.roleRequiredMessage;
            return false;
        }
        if (CloudIAMConnection.isDisconnectRequest(cloudIAM)) {
            return true;
        }
        try {
            await CloudIAMConnection.verify(cloudIAM);
            return true;
        } catch (e) {
            this.message =
                e instanceof BadRequestException
                    ? // eslint-disable-next-line @typescript-eslint/ban-ts-comment
                      //@ts-ignore
                      e.getResponse()?.message ?? e.message
                    : `Unable to validate the provided IAM role: ${cloudIAM?.iamRoleArn}`;
            return false;
        }
    }

    defaultMessage(args: ValidationArguments) {
        return this.message ?? `Unable to validate the provided IAM role`;
    }
}

export function ValidCloudIAM(validationOptions?: ValidationOptions) {
    return function (object: unknown, propertyName: string) {
        registerDecorator({
            name: 'ValidCloudIAM',
            target: object.constructor,
            propertyName: propertyName,
            constraints: [],
            options: validationOptions,
            validator: ValidCloudIAMRule,
        });
    };
}
