import { Test, TestingModule } from '@nestjs/testing';
import { createMock } from '@golevelup/ts-jest';
import { BadRequestException } from '@nestjs/common';
import { validate } from 'class-validator';
import { plainToInstance } from 'class-transformer';
import { IAMClient, CreateRoleCommand, PutRolePolicyCommand } from '@aws-sdk/client-iam';

import { SettingsService } from './settings.service.js';
import { InfluxService } from '../influx/influx.service.js';
import { UpdateSettingsDto } from './dto/update-settings.dto.js';

const ACCOUNT = '600000000042';
const EXTERNAL_ID = 'scraper-external-id';
const arn = (role: string) => `arn:aws:iam::${ACCOUNT}:role/${role}`;

const trustPolicy = (externalId?: string) =>
    JSON.stringify({
        Version: '2012-10-17',
        Statement: [
            {
                Effect: 'Allow',
                Principal: { AWS: `arn:aws:iam::${ACCOUNT}:root` },
                Action: 'sts:AssumeRole',
                ...(externalId ? { Condition: { StringEquals: { 'sts:ExternalId': externalId } } } : {}),
            },
        ],
    });

const readOnlyPolicy = JSON.stringify({
    Version: '2012-10-17',
    Statement: [{ Effect: 'Allow', Action: ['ec2:Describe*'], Resource: '*' }],
});

const iam = new IAMClient({});

const ensureRole = async (RoleName: string, externalId?: string, withEc2Read = true) => {
    try {
        await iam.send(new CreateRoleCommand({ RoleName, AssumeRolePolicyDocument: trustPolicy(externalId) }));
    } catch (e) {
        // role already exists
    }
    if (withEc2Read) {
        await iam.send(new PutRolePolicyCommand({ RoleName, PolicyName: 'read', PolicyDocument: readOnlyPolicy }));
    }
};

describe('Scraper role (cloudIAM) verification', () => {
    let service: SettingsService;
    let influxService: InfluxService;
    const businessID = 'some-business-id';
    const subject = 'some-subject';

    beforeAll(async () => {
        await ensureRole('spec-scraper-good', EXTERNAL_ID);
        await ensureRole('spec-scraper-open');
        await ensureRole('spec-scraper-no-ec2', EXTERNAL_ID, false);
    });

    beforeEach(async () => {
        const module: TestingModule = await Test.createTestingModule({ providers: [SettingsService] })
            .useMocker(createMock)
            .compile();
        service = module.get(SettingsService);
        influxService = module.get(InfluxService);
        jest.spyOn(influxService, 'loadPoints').mockResolvedValue(undefined);
    });

    afterEach(() => jest.clearAllMocks());

    it('saves a role which can be assumed with the external id and can read the inventory', async () => {
        const cloudIAM = { iamRoleArn: arn('spec-scraper-good'), externalId: EXTERNAL_ID };
        const { data } = await service.update({ businessID, subject, cloudIAM });
        expect(data[0].cloudIAM).toEqual(cloudIAM);
        expect(influxService.loadPoints).toBeCalledTimes(1);
    });

    it('rejects a role which cannot be assumed with the supplied external id, and writes nothing', async () => {
        await expect(
            service.update({ businessID, subject, cloudIAM: { iamRoleArn: arn('spec-scraper-good'), externalId: 'nope' } }),
        ).rejects.toBeInstanceOf(BadRequestException);
        expect(influxService.loadPoints).not.toBeCalled();
    });

    it('rejects a role which does not exist', async () => {
        await expect(
            service.update({ businessID, subject, cloudIAM: { iamRoleArn: arn('spec-does-not-exist') } }),
        ).rejects.toBeInstanceOf(BadRequestException);
        expect(influxService.loadPoints).not.toBeCalled();
    });

    it('rejects a role which is assumable but cannot read the instance inventory', async () => {
        await expect(
            service.update({
                businessID,
                subject,
                cloudIAM: { iamRoleArn: arn('spec-scraper-no-ec2'), externalId: EXTERNAL_ID },
            }),
        ).rejects.toBeInstanceOf(BadRequestException);
        expect(influxService.loadPoints).not.toBeCalled();
    });

    it('treats a blank role as a disconnect and clears the external id', async () => {
        const { data } = await service.update({
            businessID,
            subject,
            cloudIAM: { iamRoleArn: '', externalId: 'left-over-external-id' },
        });
        expect(data[0].cloudIAM).toEqual({ iamRoleArn: '', externalId: '' });
        expect(influxService.loadPoints).toBeCalledTimes(1);
    });

    it('rejects a settings block which names no role at all', async () => {
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        //@ts-ignore
        await expect(service.update({ businessID, subject, cloudIAM: {} })).rejects.toBeInstanceOf(BadRequestException);
        expect(influxService.loadPoints).not.toBeCalled();
    });

    it('does not touch the saved role when the update does not mention it', async () => {
        const { data } = await service.update({ businessID, subject, logoUrl: 'https://example.com/logo.png' });
        expect(data[0].logoUrl).toEqual('https://example.com/logo.png');
        expect(influxService.loadPoints).toBeCalledTimes(1);
    });

    describe('request validation', () => {
        const errorsFor = async (cloudIAM) =>
            validate(plainToInstance(UpdateSettingsDto, { businessID, cloudIAM }), { whitelist: true });

        it('fails validation for a role that cannot be assumed', async () => {
            const errors = await errorsFor({ iamRoleArn: 'wow a fake role', externalId: 'foobar' });
            expect(errors.length).toBeGreaterThan(0);
            expect(JSON.stringify(errors)).toEqual(expect.stringContaining('IAM'));
        });

        it('fails validation when no role is named', async () => {
            const errors = await errorsFor({ externalId: 'foobar' });
            expect(errors.length).toBeGreaterThan(0);
        });

        it('passes validation for a disconnect', async () => {
            const errors = await errorsFor({ iamRoleArn: '' });
            expect(errors).toEqual([]);
        });

        it('passes validation for a verified role', async () => {
            const errors = await errorsFor({ iamRoleArn: arn('spec-scraper-open') });
            expect(errors).toEqual([]);
        });
    });
});
