import { fromTemporaryCredentials } from '@aws-sdk/credential-providers';
import { serializeError } from 'serialize-error';

import { readInstanceInventory } from '../../utils/aws/awsEc2.js';

/**
 * The shape of the cloud IAM information which is stored on a business' settings.
 * <br><br>
 * A structural type is used here so this module can be consumed by both the settings DTOs and the
 * settings entities without creating a circular import.
 */
export interface CloudIAMLike {
    iamRoleArn?: string;
    externalId?: string;
}

/**
 * A verified cloud IAM connection, or a disconnection, which is safe to persist onto the settings.
 */
export interface VerifiedCloudIAM {
    iamRoleArn: string;
    externalId: string;
}

/**
 * Handles everything to do with the scraper role (`cloudIAM`) a customer connects to MeteringCo.
 * <br><br>
 * Before a role is saved onto a business' settings it must be proven that:
 * <ol>
 *  <li>MeteringCo can assume the role with the external ID which was supplied on the request</li>
 *  <li>The credentials which come back from that assumption can read the EC2 instance inventory collection relies on</li>
 * </ol>
 * If either of those checks fail the whole settings update is rejected with a bad request, nothing is persisted.
 */
export class CloudIAMConnection {
    private static readonly logger = new Logger(CloudIAMConnection.name);

    /**
     * The region used to verify the connection, collection assumes the role in `us-east-1`.
     */
    public static readonly verificationRegion = 'us-east-1';

    public static readonly roleRequiredMessage =
        'cloudIAM: An iamRoleArn must be supplied, send an empty iamRoleArn to disconnect the currently connected IAM role';

    /**
     * The value stored when a customer disconnects their scraper role, the external ID is always cleared with the role.
     */
    public static disconnected(): VerifiedCloudIAM {
        return { iamRoleArn: '', externalId: '' };
    }

    /**
     * `true` when the settings block sent by the customer actually names a role.
     */
    public static namesRole(cloudIAM: CloudIAMLike): boolean {
        return typeof cloudIAM?.iamRoleArn === 'string';
    }

    /**
     * `true` when the customer sent a blank role, which means disconnect.
     */
    public static isDisconnectRequest(cloudIAM: CloudIAMLike): boolean {
        return CloudIAMConnection.namesRole(cloudIAM) && cloudIAM.iamRoleArn.trim() === '';
    }

    /**
     * Assumes the supplied role with the supplied external ID.
     *
     * @throws BadRequestException when the role cannot be assumed
     */
    private static async assume({ iamRoleArn, externalId }: CloudIAMLike) {
        try {
            const credentialProvider = fromTemporaryCredentials({
                params: {
                    RoleArn: iamRoleArn,
                    ExternalId: externalId ? externalId : undefined,
                    RoleSessionName: 'meteringco-settings-validation',
                },
                clientConfig: { region: CloudIAMConnection.verificationRegion },
            });
            return await credentialProvider();
        } catch (e) {
            CloudIAMConnection.logger.error(
                `Failed to assume the IAM role ${iamRoleArn}: ${JSON.stringify(serializeError(e))}`,
            );
            throw new BadRequestException(
                `Unable to assume the provided IAM role: ${iamRoleArn}${
                    externalId ? ` with the provided externalId: ${externalId}` : ' without an externalId'
                }. Confirm the role exists and that its trust policy allows MeteringCo to assume it with that externalId`,
            );
        }
    }

    /**
     * Proves the credentials returned by assuming the role can read the instance inventory used by collection.
     *
     * @throws BadRequestException when the inventory cannot be read
     */
    private static async readInventory(credentials, { iamRoleArn }: CloudIAMLike) {
        try {
            await readInstanceInventory(credentials, CloudIAMConnection.verificationRegion);
        } catch (e) {
            CloudIAMConnection.logger.error(
                `The IAM role ${iamRoleArn} cannot read the instance inventory: ${JSON.stringify(serializeError(e))}`,
            );
            throw new BadRequestException(
                `The provided IAM role: ${iamRoleArn} was assumed but it cannot read the EC2 instance inventory used to collect usage. Grant the role permission to ec2:DescribeInstances`,
            );
        }
    }

    /**
     * Verifies a connected scraper role, both the assumption and the read of the instance inventory.
     *
     * @throws BadRequestException when either check fails
     */
    public static async verify(cloudIAM: CloudIAMLike): Promise<void> {
        const credentials = await CloudIAMConnection.assume(cloudIAM);
        await CloudIAMConnection.readInventory(credentials, cloudIAM);
    }

    /**
     * Validates the `cloudIAM` block of a settings update and returns the value which should be saved.
     * <br><br>
     * A blank role is a disconnect, and clears the external ID. A block which names no role at all is invalid.
     *
     * @throws BadRequestException when the block names no role, or when the named role fails verification
     */
    public static async resolveUpdate(cloudIAM: CloudIAMLike): Promise<VerifiedCloudIAM> {
        if (!CloudIAMConnection.namesRole(cloudIAM)) {
            throw new BadRequestException(CloudIAMConnection.roleRequiredMessage);
        }
        if (CloudIAMConnection.isDisconnectRequest(cloudIAM)) {
            CloudIAMConnection.logger.log('Blank iamRoleArn supplied, disconnecting the scraper role');
            return CloudIAMConnection.disconnected();
        }
        const requestedConnection: VerifiedCloudIAM = {
            iamRoleArn: cloudIAM.iamRoleArn,
            externalId: cloudIAM.externalId ? cloudIAM.externalId : '',
        };
        await CloudIAMConnection.verify(requestedConnection);
        return requestedConnection;
    }
}
